import {config,getKey} from './config.mjs';
import {wireMessages,nativeParts} from './native.mjs';
export async function* stream(options,attribution={},fetcher=fetch,keyProvider=getKey){
 const c=config(),media=options.purpose?{parts:[],commit(){}}:nativeParts(options.messages||[]),messages=wireMessages(options);if(media.parts.length)messages.push({role:'user',content:[{type:'text',text:'以下是本轮实际提供的原始媒体，请直接原生听看，不用文字占位推测。'},...media.parts]});
 const r=await fetcher(c.baseURL.replace(/\/$/,'')+'/chat/completions',{method:'POST',signal:options.signal,headers:{...attribution,Authorization:'Bearer '+keyProvider(),'Content-Type':'application/json','X-DashScope-OssResourceResolve':'enable'},body:JSON.stringify({model:options.model||c.model,messages,tools:options.tools?.length?options.tools.map(t=>({type:'function',function:{name:t.name,description:t.description,parameters:t.parameters}})):undefined,modalities:['text'],stream:true,stream_options:{include_usage:true},enable_thinking:false,max_tokens:options.maxTokens||131072})});
 if(!r.ok)throw Error('Qwen HTTP '+r.status+'：'+await r.text());
 let buffer='',text='',thinking='',startedText=false,startedThinking=false,usage,finishReason;const calls=[],decoder=new TextDecoder();
 for await(const data of r.body){buffer+=decoder.decode(data,{stream:true});let n;while((n=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,n).trim();buffer=buffer.slice(n+1);if(!line.startsWith('data:')||line.slice(5).trim()==='[DONE]')continue;const chunk=JSON.parse(line.slice(5).trim());if(chunk.error)throw Error(chunk.error.message||'模型调用失败');if(chunk.usage)usage=chunk.usage;const choice=chunk.choices?.[0];if(choice?.finish_reason)finishReason=choice.finish_reason;const d=choice?.delta;if(d?.content){if(!startedText){yield {type:'block-start',index:0,blockType:'text'};startedText=true;}text+=d.content;yield {type:'text-delta',index:0,text:d.content};}if(d?.reasoning_content){if(!startedThinking){yield {type:'block-start',index:1,blockType:'reasoning'};startedThinking=true;}thinking+=d.reasoning_content;yield {type:'reasoning-delta',index:1,text:d.reasoning_content};}for(const t of d?.tool_calls||[]){const call=calls[t.index]??={id:t.id,name:'',arguments:''};if(t.id)call.id=t.id;call.name+=t.function?.name||'';call.arguments+=t.function?.arguments||'';}}}
 if(startedText)yield {type:'block-end',index:0,block:{type:'text',text}};if(startedThinking)yield {type:'block-end',index:1,block:{type:'reasoning',text:thinking}};
 for(let i=0;i<calls.length;i++){const c=calls[i];if(!c)continue;const index=i+2;yield {type:'block-start',index,blockType:'tool-call'};yield {type:'tool-call-delta',index,id:c.id,name:c.name,argumentsDelta:c.arguments};yield {type:'block-end',index,block:{type:'tool-call',id:c.id,name:c.name,arguments:c.arguments}};}
 if(usage){const cached=usage.prompt_tokens_details?.cached_tokens||0;yield {type:'usage',usage:{inputTokens:Math.max(0,(usage.prompt_tokens||0)-cached),outputTokens:usage.completion_tokens||0,totalTokens:usage.total_tokens,cacheReadTokens:cached}};}
 if(!finishReason)throw Error('模型流意外中断，未收到完成标记。');
 media.commit();yield {type:'finish',reason:{kind:calls.length?'tool-calls':finishReason==='length'?'max-tokens':'stop'}};
}
